'use strict';
window.AtlasAnimations=(()=>{
 const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
 const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const models={
  eclipse:{label:'Eclipses',tag:'ESPACIO',source:'#ciencia/luna-eclipses',steps:[
   ['1 · Alineación','La Luna se mueve alrededor de la Tierra, pero no siempre queda en la misma línea que el Sol.'],
   ['2 · Sombra parcial','Cuando la alineación es aproximada, una parte de la sombra alcanza la Tierra y vemos un eclipse parcial.'],
   ['3 · Sombra total','En una alineación precisa, la sombra central puede cubrir una zona pequeña de la Tierra: eclipse total para quienes están allí.'],
   ['4 · Una pregunta clave','El eclipse no ocurre cada mes porque la órbita de la Luna está inclinada respecto al plano de la órbita terrestre.']
  ]},
  seasons:{label:'Estaciones',tag:'TIERRA',source:'#ciencia/estaciones',steps:[
   ['1 · La Tierra se inclina','La Tierra gira alrededor del Sol con un eje inclinado. Esa inclinación es la clave del cambio estacional.'],
   ['2 · Más luz en un hemisferio','Cuando un hemisferio recibe luz más directa y días más largos, allí es verano; en el otro es invierno.'],
   ['3 · Cambia la posición','Meses después, la Tierra está en otra parte de su órbita y cambia qué hemisferio recibe más energía.'],
   ['4 · No es la distancia','Las estaciones no se explican principalmente por estar más cerca o más lejos del Sol, sino por la inclinación y la luz recibida.']
  ]},
  gravity:{label:'Gravedad',tag:'ESPACIO · TIERRA',source:'#ciencia/gravedad',steps:[
   ['1 · Dos masas','Todo objeto con masa puede atraer gravitacionalmente a otro objeto con masa.'],
   ['2 · Menor distancia','Al acercar las masas, la interacción gravitatoria se vuelve más intensa. El dibujo exagera el efecto para hacerlo visible.'],
   ['3 · Más masa','Una masa mayor produce una atracción mayor. Por eso la Tierra domina el movimiento de la Luna y de los satélites cercanos.'],
   ['4 · Modelo y realidad','Este esquema ayuda a razonar; no muestra las trayectorias completas ni reemplaza una ecuación o una medición.']
  ]},
  volcano:{label:'Volcanes',tag:'TIERRA',source:'#ciencia/volcanes',steps:[
   ['1 · Energía interna','El interior terrestre conserva calor. El magma se forma en ciertas condiciones y puede acumularse.'],
   ['2 · Ascenso del magma','El magma puede subir por fracturas o conductos. La presión, los gases y la viscosidad influyen en el comportamiento.'],
   ['3 · Erupción','Si el material alcanza la superficie, puede salir lava, ceniza y gases. Cada volcán tiene una historia y un riesgo distinto.'],
   ['4 · Leer el paisaje','La forma del volcán no basta para predecir una erupción: se estudian señales, materiales, registros y monitoreo.']
  ]},
  plates:{label:'Placas tectónicas',tag:'TIERRA · RELIEVE',source:'#ciencia/placas-tectonicas',steps:[
   ['1 · Placas que se separan','En un límite divergente, las placas se alejan y puede formarse nueva corteza.'],
   ['2 · Placas que chocan','En un límite convergente, una placa puede hundirse o ambas pueden deformarse y levantar montañas.'],
   ['3 · Placas que se deslizan','En un límite transformante, las placas se desplazan lateralmente; la fricción puede acumular energía.'],
   ['4 · Un planeta dinámico','Los límites no son líneas perfectas en el paisaje. Son modelos para entender terremotos, volcanes y montañas.']
  ]},
  history:{label:'Mapa narrado de una ruta',tag:'HISTORIA',source:'#ruta/independencia',steps:[
   ['1 · Ubicar el punto de partida','Un mapa histórico ayuda a preguntar dónde ocurre un proceso. Este esquema es pedagógico y no representa fronteras de la época.'],
   ['2 · Seguir conexiones','Al activar la siguiente escena, observamos cómo una ruta puede relacionar lugares, decisiones y movimientos.'],
   ['3 · Cambiar de escala','Una ruta nacional no explica todas las experiencias locales. Hay que volver a los municipios, comunidades y fuentes.'],
   ['4 · Investigar','El mapa abre preguntas: ¿quién se movió?, ¿qué documento lo registra?, ¿qué voces no aparecen?']
  ]}
 };
 let active='eclipse',step=0,timer=null,playing=false;
 function tabs(){return Object.entries(models).map(([id,m])=>`<button data-animation-model="${id}" aria-pressed="${active===id}">${safe(m.label)}</button>`).join('')}
 function eclipseSvg(){const moon=[230,300,370,410][step];return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Animación conceptual de un eclipse"><rect width="800" height="300" rx="16" fill="#0d1b33"/><text x="24" y="28" fill="#b8e8ec" font-size="14" font-weight="700">SOL · LUNA · TIERRA · MODELO NO A ESCALA</text><circle cx="100" cy="160" r="48" fill="#de8c24"/><circle cx="450" cy="160" r="32" fill="#4e91b5"/><circle cx="${moon}" cy="160" r="12" fill="#d9e2e9"/><path d="M148 160H${moon-16}" stroke="#f7d8af" stroke-dasharray="5 6"/><path d="M${moon+16} 160H418" stroke="#f7d8af" stroke-dasharray="5 6"/><path d="M${moon+8} 174 L${Math.min(445,moon+42)} 206 L${Math.min(470,moon+62)} 206 L${moon+8} 184Z" fill="#253653" opacity="${step>0?.55:0}"/><text x="100" y="235" text-anchor="middle" fill="#fff" font-size="14">Sol</text><text x="${moon}" y="235" text-anchor="middle" fill="#fff" font-size="14">Luna</text><text x="450" y="235" text-anchor="middle" fill="#fff" font-size="14">Tierra</text><text x="560" y="72" fill="#c8d9ee" font-size="13">${step===0?'Órbita inclinada':step===1?'Sombra parcial':step===2?'Sombra central':'Pregunta: ¿por qué no cada mes?'}</text></svg>`}
 function seasonsSvg(){const pos=[[175,90],[400,65],[625,90],[400,230]][step];return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Animación conceptual de las estaciones"><rect width="800" height="300" rx="16" fill="#0d1b33"/><text x="24" y="28" fill="#b8e8ec" font-size="14" font-weight="700">LA ÓRBITA Y LA INCLINACIÓN DEL EJE</text><circle cx="400" cy="150" r="42" fill="#de8c24"/><ellipse cx="400" cy="150" rx="245" ry="92" fill="none" stroke="#7b8ca5" stroke-opacity=".55" stroke-width="2"/><circle cx="${pos[0]}" cy="${pos[1]}" r="24" fill="#5ca3c7"/><line x1="${pos[0]-14}" y1="${pos[1]-36}" x2="${pos[0]+14}" y2="${pos[1]+36}" stroke="#f7d8af" stroke-width="3"/><path d="M120 255H680" stroke="#6ea9a3" stroke-width="3"/><text x="${pos[0]}" y="${pos[1]+55}" text-anchor="middle" fill="#fff" font-size="14">Tierra · ${['primavera','verano','otoño','invierno'][step]}</text><text x="28" y="278" fill="#c8d9ee" font-size="13">El eje conserva su orientación mientras la Tierra recorre su órbita.</text></svg>`}
 function gravitySvg(){const distance=[190,145,100,75][step],left=400-distance/2,right=400+distance/2,r1=22+(step*4),r2=28+(step*5);return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Animación conceptual de la gravedad"><rect width="800" height="300" rx="16" fill="#0d1b33"/><text x="24" y="28" fill="#b8e8ec" font-size="14" font-weight="700">LA ATRACCIÓN DEPENDE DE LA MASA Y LA DISTANCIA</text><circle cx="${left}" cy="150" r="${r1}" fill="#5ca3c7"/><circle cx="${right}" cy="150" r="${r2}" fill="#de8c24"/><path d="M${left+r1+10} 150H${right-r2-10}" stroke="#b8e8ec" stroke-width="${2+step}" stroke-dasharray="8 6"/><path d="M${left+r1+10} 150l12 -8v16zM${right-r2-10} 150l-12 -8v16z" fill="#b8e8ec"/><text x="${left}" y="220" text-anchor="middle" fill="#fff" font-size="14">Masa A</text><text x="${right}" y="220" text-anchor="middle" fill="#fff" font-size="14">Masa B</text><text x="550" y="78" fill="#c8d9ee" font-size="13">${step<2?'Se acercan las masas':'La interacción se representa más intensa'}</text></svg>`}
 function volcanoSvg(){const lava=step>1?'M400 235 C390 185 410 145 400 100':'M400 235 C400 220 400 210 400 200';return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Animación conceptual de un volcán"><rect width="800" height="300" rx="16" fill="#0d1b33"/><text x="24" y="28" fill="#b8e8ec" font-size="14" font-weight="700">DEL MAGMA A LA SUPERFICIE</text><path d="M180 260 L330 130 L400 115 L470 130 L620 260Z" fill="#a94e33"/><path d="M250 260 L350 170 L400 150 L450 170 L550 260Z" fill="#c47b54"/><ellipse cx="400" cy="235" rx="74" ry="25" fill="#de8c24" opacity=".85"/><path d="${lava}" fill="none" stroke="#f7d8af" stroke-width="10" stroke-linecap="round"/><path d="M400 105 C365 70 390 52 400 42 C410 52 435 70 400 105" fill="#de8c24" opacity="${step===3?.9:step>1?.45:0}"/><text x="400" y="282" text-anchor="middle" fill="#fff" font-size="14">${['Cámara magmática','Ascenso','Erupción','Observar y monitorear'][step]}</text></svg>`}
 function platesSvg(){const mode=step%3;const arrows=mode===0?'<path d="M300 170h-80M500 170h80" stroke="#b8e8ec" stroke-width="6" marker-end="url(#plateArrow)"/><text x="400" y="74" text-anchor="middle" fill="#fff" font-size="15">Divergente · se separan</text>':mode===1?'<path d="M300 170h80M500 170h-80" stroke="#b8e8ec" stroke-width="6" marker-end="url(#plateArrow)"/><text x="400" y="74" text-anchor="middle" fill="#fff" font-size="15">Convergente · chocan</text>':'<path d="M300 150h-70M500 190h70" stroke="#b8e8ec" stroke-width="6" marker-end="url(#plateArrow)"/><text x="400" y="74" text-anchor="middle" fill="#fff" font-size="15">Transformante · se deslizan</text>';return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Animación conceptual de placas tectónicas"><defs><marker id="plateArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#b8e8ec"/></marker></defs><rect width="800" height="300" rx="16" fill="#0d1b33"/><text x="24" y="28" fill="#b8e8ec" font-size="14" font-weight="700">TRES FORMAS DE MOVERSE EN UN LÍMITE</text><path d="M100 220 L300 120 L400 145 L510 120 L700 220V285H100Z" fill="#bc6a45"/><path d="M100 255 L300 205 L400 220 L510 205 L700 255V285H100Z" fill="#d89057" opacity=".85"/>${arrows}<text x="400" y="260" text-anchor="middle" fill="#f7d8af" font-size="14">Selecciona siguiente para comparar el modelo</text></svg>`}
 function historySvg(){const pts=[[145,210,'Dolores Hidalgo'],[305,130,'Guanajuato'],[490,105,'Guadalajara'],[660,175,'Ciudad de México']];const path=step===0?'':pts.slice(0,step+1).map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');return `<svg class="animation-svg" viewBox="0 0 800 300" role="img" aria-label="Mapa esquemático de una ruta histórica"><rect width="800" height="300" rx="16" fill="#2a1d22"/><text x="24" y="28" fill="#f7d8af" font-size="14" font-weight="700">RUTA ESQUEMÁTICA · NO REPRESENTA FRONTERAS HISTÓRICAS</text><path d="M115 235 C90 160 170 80 290 75 C430 25 700 75 710 190 C690 245 560 258 420 246 C300 280 190 267 115 235Z" fill="#7c6a50" opacity=".45"/><path d="${path}" fill="none" stroke="#de8c24" stroke-width="6" stroke-linecap="round" stroke-dasharray="9 6"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${i<=step?10:6}" fill="${i<=step?'#b8e8ec':'#f7d8af'}"/><text x="${p[0]}" y="${p[1]-17}" text-anchor="middle" fill="#fff" font-size="12">${p[2]}</text>`).join('')}<text x="400" y="280" text-anchor="middle" fill="#f6eadb" font-size="13">Usa el mapa para abrir preguntas y después consulta la ruta completa.</text></svg>`}
 function svg(){if(active==='eclipse')return eclipseSvg();if(active==='seasons')return seasonsSvg();if(active==='gravity')return gravitySvg();if(active==='volcano')return volcanoSvg();if(active==='plates')return platesSvg();return historySvg()}
 function stop(){if(timer){clearInterval(timer);timer=null}playing=false}
 function render(){const host=q('#animationsApp');if(!host)return;const m=models[active],info=m.steps[step];host.innerHTML=`<div class="animation-shell"><nav class="animation-tabs" aria-label="Animaciones educativas">${tabs()}</nav><div class="animation-layout"><div><div class="animation-stage ${playing?'is-playing':''}">${svg()}</div><p class="animation-credit">Esquema educativo creado para Atlas · No está a escala. La explicación completa enlaza a la ficha del tema.</p></div><aside class="animation-panel"><span class="science-label">${safe(m.tag)}</span><h2>${safe(info[0])}</h2><p>${safe(info[1])}</p><div class="animation-progress"><span>Paso ${step+1} de ${m.steps.length}</span><progress value="${step+1}" max="${m.steps.length}"></progress></div><input id="animationRange" type="range" min="0" max="${m.steps.length-1}" value="${step}" aria-label="Paso de la animación"><div class="animation-controls"><button class="atlas-outline" data-step-prev ${step===0?'disabled':''}>← Anterior</button><button class="atlas-button" data-anim-play>${playing?'Pausar':'Reproducir'}</button><button class="atlas-outline" data-step-next ${step===m.steps.length-1?'disabled':''}>Siguiente →</button></div><a class="text-link" href="${m.source}">Abrir ficha relacionada →</a></aside></div></div>`;bind()}
 function bind(){all('[data-animation-model]').forEach(b=>b.onclick=()=>{stop();active=b.dataset.animationModel;step=0;render()});q('[data-step-prev]')&&(q('[data-step-prev]').onclick=()=>{step=Math.max(0,step-1);render()});q('[data-step-next]')&&(q('[data-step-next]').onclick=()=>{step=Math.min(models[active].steps.length-1,step+1);render()});q('#animationRange')&&(q('#animationRange').oninput=e=>{step=Number(e.target.value);render()});q('[data-anim-play]')&&(q('[data-anim-play]').onclick=togglePlay)}
 function togglePlay(){if(playing){stop();render();return}playing=true;render();timer=setInterval(()=>{if(step>=models[active].steps.length-1){stop();render();return}step++;render()},1400)}
 function init(){render()}
 function route(hash){if(hash==='animaciones')render();else stop()}
 return {init,route};
})();
